const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/tax/codes',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    sort: 'SOME_STRING_VALUE',
    id: 'SOME_ARRAY_VALUE',
    code: 'SOME_ARRAY_VALUE',
    status: 'SOME_ARRAY_VALUE',
    include_rate: 'SOME_BOOLEAN_VALUE',
    erp_synced: 'SOME_BOOLEAN_VALUE',
    effective_as_of: 'SOME_STRING_VALUE',
    query: 'SOME_STRING_VALUE',
    type: 'SOME_STRING_VALUE',
    exclude_untaxed: 'SOME_BOOLEAN_VALUE',
    include_components: 'SOME_BOOLEAN_VALUE',
    include_group_membership: 'SOME_BOOLEAN_VALUE'
