var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/tax/codes?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&sort=SOME_STRING_VALUE&id=SOME_ARRAY_VALUE&code=SOME_ARRAY_VALUE&status=SOME_ARRAY_VALUE&include_rate=SOME_BOOLEAN_VALUE&erp_synced=SOME_BOOLEAN_VALUE&effective_as_of=SOME_STRING_VALUE&query=SOME_STRING_VALUE&type=SOME_STRING_VALUE&exclude_untaxed=SOME_BOOLEAN_VALUE&include_components=SOME_BOOLEAN_VALUE&include_group_membership=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

